/bin/bash -lc "cd /workspace && python3 - <<'PYEOF'
import openai_client as c

# 1) Missing key -> clear error, no key leak
try:
    c.send_prompt(\"hi\")
except c.OpenAIClientError as e:
    print(\"missing-key:\", e)

# 2) Mock the network to verify response parsing
import urllib.request, urllib.error, io
sample = {\"output\":[{\"type\":\"message\",\"role\":\"assistant\",
  \"content\":[{\"type\":\"output_text\",\"text\":\"Hello \"},{\"type\":\"output_text\",\"text\":\"there"'!"}]}]}
class FakeResp:
    def __enter__(self): return self
    def __exit__(self,*a): return False
    def read(self): return __import__("json").dumps(sample).encode()
def fake_urlopen(req, timeout=30):
    assert req.full_url == c.API_URL
    assert req.get_header("Authorization").startswith("Bearer sk-")
    assert req.get_method() == "POST"
    assert b'"'\"input\": \"ping\"' in req.data
    return FakeResp()
urllib.request.urlopen = fake_urlopen
c.os.environ[\"OPENAI_API_KEY\"] = \"sk-test\"
print(\"reply:\", repr(c.send_prompt(\"ping\")))

# 3) API error passthrough
def fake_err(req, timeout=30):
    raise urllib.error.HTTPError(req.full_url, 401, \"Unauthorized\", {}, io.BytesIO(b'{\"error\":{\"message\":\"bad key\"}}'))
urllib.request.urlopen = fake_err
try:
    c.send_prompt(\"x\")
except c.OpenAIClientError as e:
    print(\"http-error:\", e)
PYEOF"

